[{"order":1,"type":"heading","text":"URL Search Params as State Management in Next.js"},{"order":2,"type":"paragraph","text":"When building modern web applications, managing state is crucial. While React's useState and Zustand are great for component-level or global application state, URL search params offer a superior approach for shareable UI state such as filters, pagination, and search queries."},{"order":3,"type":"subheading","text":"Why Use URL Search Params for State?"},{"order":4,"type":"bullet_point","text":"Shareability: Users can copy and paste the URL to share the exact application state with others."},{"order":5,"type":"bullet_point","text":"Browser History: Back and forward buttons work naturally out of the box."},{"order":6,"type":"bullet_point","text":"Server-Side Rendering: Next.js Server Components can read the search params directly on the initial request, improving SEO and performance."},{"order":7,"type":"subheading","text":"Implementing Search State with Next.js Hooks"},{"order":8,"type":"paragraph","text":"In Next.js App Router, we use the useSearchParams, usePathname, and useRouter hooks from next/navigation to read and update the URL search parameters."},{"order":9,"type":"code","text":"'use client';

import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { useDebouncedCallback } from 'use-debounce';

export default function SearchBar() {
  const searchParams = useSearchParams();
  const pathname = usePathname();
  const { replace } = useRouter();

  const handleSearch = useDebouncedCallback((term) => {
    const params = new URLSearchParams(searchParams);
    if (term) {
      params.set('query', term);
    } else {
      params.delete('query');
    }
    replace(`${pathname}?${params.toString()}`);
  }, 300);

  return (
    <div className="relative flex flex-1 flex-shrink-0">
      <input
        placeholder="Search..."
        onChange={(e) => handleSearch(e.target.value)}
        defaultValue={searchParams.get('query')?.toString()}
      />
    </div>
  );
}"},{"order":10,"type":"subheading","text":"Reading State on the Server"},{"order":11,"type":"paragraph","text":"One of the biggest advantages in Next.js is that page components receive searchParams as a prop. This allows us to fetch filtered data on the server without needing client-side useEffect hooks for API calls."},{"order":12,"type":"code","text":"export default async function Page({
  searchParams,
}) {
  const query = searchParams?.query || '';
  const data = await fetchFilteredData(query);

  return (
    <main>
      <SearchBar />
      <DataTable data={data} />
    </main>
  );
}"},{"order":13,"type":"subheading","text":"Best Practices"},{"order":14,"type":"bullet_point","text":"Always debounce user input (like search bars) to prevent excessive history stack entries and re-renders."},{"order":15,"type":"bullet_point","text":"Use router.replace instead of router.push for filter states so that changing a filter does not add a new entry to the browser history stack every single keystroke."}]
